{
		CloseMainMenuPopup();
		WindowSearchKeyword windowSearchKeyword = new WindowSearchKeyword();
		windowSearchKeyword.Owner = System.Windows.Application.Current.MainWindow;
		windowSearchKeyword.Show();
		windowSearchKeyword.BringIntoView();
