			if (key <= Key.S)
			{
				switch (key)
				{
				case Key.I:
					if (Keyboard.Modifiers.HasFlag(ModifierKeys.Shift) && FeatureHelper.HasFeature(Features.ShowDebugFeatures.ToString()))
					{
						ViewModelLocator.Current.DebugDesignInfoVM.ShowDesignInfo();
