						}
					}
					break;
				case Key.S:
					ViewModelLocator.Current.MainVM.SaveCurrentDesign();
					break;
				}
			}
			else if (key <= Key.Z)
			{
				switch (key)
				{
				case Key.Z:
					ViewModelLocator.Current.MainVM.Undo();
					break;
				case Key.Y:
